    {type:'berry',  name:'野果',   item:'yeguo'},
    {type:'copper', name:'铜矿',   item:'tongkuang'},
    {type:'silver', name:'银矿',   item:'yinkuang'},
    {type:'jade',   name:'玉石',   item:'jade'},
    {type:'salt',   name:'盐矿',   item:'yan'}
