    var DEF = (global.LF.PLACE_DEFAULTS && global.LF.PLACE_DEFAULTS.field) || {};
    var richness = (p.richness!=null)? p.richness : (DEF.richness!=null?DEF.richness:0.5);
    var risk = (p.risk!=null)? p.risk : (DEF.risk!=null?DEF.risk:0.3);
