          hp: ed.hp, maxHp: ed.hp,
          atk: ed.atk, def: ed.def, spd: ed.spd,
          mp: 0, maxMp: 0, rage: 0, maxRage: 100,
          skills: ed.skills || [],
          ai: ed.ai || 'aggressive',
          element: ed.element || '无',
          hitRate: 0.9,
          buffs: [], dots: [],
          defStance: false, stunNext: false,
          forceEff: {},
