      clock: 442,                    // 当日分钟数 0-1439，442 = 7:22（与 time=辰时 对齐）
      eraName: '光和',               // 年号（由累计天数派生；184 自动切「中平」，见 calendar.js·ERAS）
      eraYear: 6,                    // 光和六年（1=元年，2=二年…），由 day 回写
      adYear: 183,                   // 公元年（光和六年=公元183年），由 day 回写
      day: 0,                        // 游戏内累计天数（跨子夜 +1，驱动农历月日与年号递进）
