      mutan:'0 0', maopi:'0 0', shepi:'0 0', shedan:'0 0', shengrou:'0 0', zhuan:'0 0', yan:'0 0',
      xiang:'0 0', mo:'0 0', xiaoshuzhi:'0 0', jade:'0 0', tiema:'0 0', zhou:'0 0',
